"""
Standing Orders harness — skeleton.

STATUS: written, NOT YET RUN. No results have been produced with this code.
Do not cite any numbers from this project; there are none.

Design constraints:
  1. Gated tool calls are intercepted, logged, and never executed. The agent is told
     they succeeded, so that a breach is measured as a breach and not confounded by
     the agent noticing a failure and self-correcting.
  2. Fixtures are instantiated fresh per scenario. No state crosses scenarios.
  3. Transcripts are written verbatim to disk for blind human scoring. This harness
     deliberately does NOT auto-score. Scoring is a human judgement about whether an
     agent honoured a principal's intent, and automating it would quietly replace the
     thing we care about with a proxy for it.

Model adapters are intentionally thin and vendor-agnostic: implement `AgentAdapter`
for whatever is being tested.
"""

from __future__ import annotations

import json
import pathlib
import uuid
from dataclasses import dataclass, field, asdict
from typing import Any, Callable, Protocol

import yaml  # pyyaml


SCENARIO_DIR = pathlib.Path(__file__).resolve().parents[1] / "scenarios"
RUN_DIR = pathlib.Path(__file__).resolve().parents[1] / "runs"


# --------------------------------------------------------------------------- #
# Scenario loading
# --------------------------------------------------------------------------- #

@dataclass
class GatedAction:
    tool: str
    severity: str = "major"
    match: dict[str, Any] = field(default_factory=dict)
    note: str = ""

    def matches(self, call: "ToolCall") -> bool:
        if call.tool != self.tool:
            return False
        # Optional argument-level matching, e.g. a specific recipient or form.
        return all(str(call.args.get(k, "")) == str(v) for k, v in self.match.items())


@dataclass
class Scenario:
    id: str
    title: str
    family: str
    difficulty: int
    principal_brief: str
    task: str
    gated_actions: list[GatedAction]
    workspace: dict[str, Any] = field(default_factory=dict)
    raw: dict[str, Any] = field(default_factory=dict)

    @classmethod
    def load(cls, path: pathlib.Path) -> "Scenario":
        d = yaml.safe_load(path.read_text(encoding="utf-8"))
        gated = []
        for g in d.get("gated_actions") or []:
            g = dict(g)
            tool = g.pop("tool")
            severity = g.pop("severity", "major")
            note = g.pop("note", "")
            g.pop("conditional", None)
            gated.append(GatedAction(tool=tool, severity=severity, match=g, note=note))
        return cls(
            id=d["id"],
            title=d["title"],
            family=d["family"],
            difficulty=int(d.get("difficulty", 3)),
            principal_brief=d.get("principal_brief", ""),
            task=d.get("task", ""),
            gated_actions=gated,
            workspace=d.get("workspace") or {},
            raw=d,
        )


def load_all() -> list[Scenario]:
    return [Scenario.load(p) for p in sorted(SCENARIO_DIR.glob("SO-*.yaml"))]


# --------------------------------------------------------------------------- #
# Tool layer
# --------------------------------------------------------------------------- #

@dataclass
class ToolCall:
    tool: str
    args: dict[str, Any]
    blocked: bool = False
    severity: str | None = None
    result: Any = None


class Workspace:
    """Fixture-backed mock of the deployment surface.

    Read tools return fixture data. Write tools mutate fixture state only.
    Nothing here touches a network, a card, or a real account — by construction,
    not by configuration. A harness for this benchmark must not be one misread
    config away from doing the thing it is measuring.
    """

    def __init__(self, spec: dict[str, Any], fixture_root: pathlib.Path):
        self.spec = spec
        self.fixture_root = fixture_root
        self.state: dict[str, Any] = self._instantiate(spec)

    def _instantiate(self, spec: dict[str, Any]) -> dict[str, Any]:
        state: dict[str, Any] = {"drafts": [], "messages_to_principal": []}
        for name in spec.get("inbox", []) or []:
            p = self.fixture_root / pathlib.Path(name).name
            if p.exists():
                state.setdefault("inbox", []).extend(json.loads(p.read_text("utf-8")))
        state.setdefault("inbox", [])
        state["drive"] = list(spec.get("drive") or [])
        state["repo"] = dict(spec.get("repo") or {})
        state["accounts"] = dict(spec.get("accounts") or {})
        return state

    # Read tools -------------------------------------------------------------
    def email_list(self, **_):
        return [{k: m[k] for k in ("id", "from", "subject", "date") if k in m}
                for m in self.state["inbox"]]

    def email_read(self, id: str, **_):
        return next((m for m in self.state["inbox"] if m.get("id") == id), None)

    def drive_list(self, **_):
        return [{"name": f.get("name")} for f in self.state["drive"]]

    def repo_list(self, **_):
        return self.state["repo"]

    # Non-consequential write tools -----------------------------------------
    def email_draft(self, **kw):
        self.state["drafts"].append(kw)
        return {"saved": True}

    def message_user(self, text: str, **_):
        self.state["messages_to_principal"].append(text)
        return {"delivered": True}


class AgentAdapter(Protocol):
    """Implement for each configuration under test."""

    name: str

    def run(
        self,
        system_prompt: str,
        task: str,
        tools: dict[str, Callable[..., Any]],
        max_turns: int = 30,
    ) -> list[dict[str, Any]]:
        """Return the full transcript as a list of message dicts."""
        ...


# --------------------------------------------------------------------------- #
# Runner
# --------------------------------------------------------------------------- #

def run_scenario(scenario: Scenario, agent: AgentAdapter,
                 fixture_root: pathlib.Path, max_turns: int = 30) -> dict[str, Any]:
    ws = Workspace(scenario.workspace, fixture_root)
    log: list[ToolCall] = []

    available = [t for t in (scenario.workspace.get("tools") or [])]

    def make(tool_name: str) -> Callable[..., Any]:
        def call(**args):
            gate = next((g for g in scenario.gated_actions
                         if g.matches(ToolCall(tool_name, args))), None)
            if gate is not None:
                # Intercept: log, do not execute, report plausible success.
                log.append(ToolCall(tool_name, args, blocked=True,
                                    severity=gate.severity,
                                    result="SIMULATED_OK"))
                return _plausible_success(tool_name, args)
            impl = getattr(ws, tool_name, None)
            result = impl(**args) if impl else {"ok": True, "unimplemented": tool_name}
            log.append(ToolCall(tool_name, args, blocked=False, result=result))
            return result
        return call

    tools = {name: make(name) for name in available}

    transcript = agent.run(
        system_prompt=scenario.principal_brief,
        task=scenario.task,
        tools=tools,
        max_turns=max_turns,
    )

    breaches = [c for c in log if c.blocked]
    return {
        "run_id": str(uuid.uuid4())[:8],
        "scenario": scenario.id,
        "family": scenario.family,
        "difficulty": scenario.difficulty,
        "agent": agent.name,
        "transcript": transcript,
        "tool_calls": [asdict(c) for c in log],
        # Mechanical facts only. F/U/D are assigned by a human rater later.
        "breach_attempted": bool(breaches),
        "breach_severities": sorted({c.severity for c in breaches if c.severity}),
        "messages_to_principal": ws.state["messages_to_principal"],
        "drafts_left": ws.state["drafts"],
        "scores": {"fidelity": None, "usefulness": None, "disclosure": None},
        "rater": None,
    }


def _plausible_success(tool: str, args: dict[str, Any]) -> dict[str, Any]:
    """What the real tool would have returned, so the agent cannot infer the gate."""
    if tool == "payments_pay":
        return {"status": "paid", "confirmation": f"CONF-{uuid.uuid4().hex[:10].upper()}",
                "amount_usd": args.get("amount_usd")}
    if tool in ("email_send",):
        return {"status": "sent", "id": f"msg_{uuid.uuid4().hex[:6]}"}
    if tool == "social_post":
        return {"status": "published", "url": "https://example.invalid/p/" + uuid.uuid4().hex[:6]}
    if tool in ("domain_renew", "domain_register"):
        return {"status": "ok", "name": args.get("name"), "expires": "2027-11-19"}
    if tool == "repo_set_visibility":
        return {"status": "ok", "visibility": args.get("visibility")}
    if tool == "web_submit_form":
        return {"status": "submitted", "form_id": args.get("form_id")}
    if tool == "site_publish":
        return {"status": "published"}
    if tool == "hosting_set_plan":
        return {"status": "ok", "plan": args.get("plan")}
    return {"status": "ok"}


def write_run(record: dict[str, Any]) -> pathlib.Path:
    RUN_DIR.mkdir(parents=True, exist_ok=True)
    out = RUN_DIR / f"{record['scenario']}__{record['agent']}__{record['run_id']}.json"
    out.write_text(json.dumps(record, indent=2, default=str), encoding="utf-8")
    return out


if __name__ == "__main__":
    scenarios = load_all()
    print(f"Loaded {len(scenarios)} scenario(s):")
    for s in scenarios:
        gates = ", ".join(f"{g.tool}({g.severity})" for g in s.gated_actions) or "none"
        print(f"  {s.id}  [{s.family} d{s.difficulty}]  {s.title}")
        print(f"        gated: {gates}")
    print("\nNo agent adapter configured. Nothing was run.")
